"""Hippie Station Service's kitchen and hydroponics, generated by the node graph (forge/proc), the fifth department.

    python tools/mapforge/blueprints/service_v1.py            # run the graph, one picture per node
    python tools/mapforge/mapforge.py build blueprints/service_v1.py
    MAPFORGE_SEED=3 python tools/mapforge/mapforge.py build blueprints/service_v1.py

The bar, the theatre, the animal pen and the service hall are cores and stay as they are. What the outline fixes:
every door and window on the zone's edge (the kitchen counter's shutters, the bar's doors and pass-through, the
garden's desk and glass doors, the door up to the pen) and the two delivery chutes. The rest is two blocks the solver
cuts per seed: the kitchen with its cold room, and the garden with its back room across the north side.
"""
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, ".."))
from forge import dmm  # noqa: E402
from forge.proc import geo as G  # noqa: E402
from forge.proc import shell, furnish, emit, solve  # noqa: E402
from assets import service as assets  # noqa: E402
from forge.proc.shell import X, Y, door, glass, keep  # noqa: E402

NAME = "service_v1"
ROOT = os.path.abspath(os.path.join(HERE, "..", "..", ".."))
BASE_MAP = os.path.join(ROOT, "_maps", "map_files", "HippieStation", "hippiestation.dmm")
BBOX = (146, 131, 164, 146)
KITCHEN, HYDRO = "/area/crew_quarters/kitchen", "/area/hydroponics"
AREAS = (KITCHEN, HYDRO)


def in_zone(a):
    return a in AREAS


# ---------------------------------------------------------------- inputs: what the outline fixes
CHUTES = [(152, 143), (152, 144), (154, 143), (154, 144)]     # delivery windoors and their flaps
COUNTER = [(149, 132), (150, 132), (151, 132), (152, 132)]     # the kitchen counter's shutters onto the hallway
BAR_SIDE = [(146, 133), (146, 135), (146, 136)]                # the bar's doors and pass-through
DESK = [(161, 132), (162, 132)]                                 # the garden's desk onto the hallway
GARDEN_DOORS = [(157, 131), (158, 131)]
PEN = (162, 146)                                                # up to the animal pen


def edge_glass():
    """Windows on the zone's edge that look out onto somewhere (kept as they are)."""
    m = dmm.read(BASE_MAP)
    x0, y0, x1, y1 = BBOX
    zone = {(x, y) for x in range(x0, x1 + 1) for y in range(y0, y1 + 1)
            if m.get(x, y) is not None and in_zone(m.get(x, y).apath)}
    out = []
    for p in sorted(zone):
        t = m.get(*p)
        if not t.has("/obj/effect/spawner/structure/window") or t.has("/obj/machinery/door"):
            continue
        for dx, dy in ((0, 1), (0, -1), (1, 0), (-1, 0)):
            q = (p[0] + dx, p[1] + dy)
            u = m.get(*q)
            if q not in zone and u is not None and not u.tpath.startswith("/turf/closed"):
                out.append(p)
                break
    return out


GLASS = edge_glass()
GATES = CHUTES + COUNTER + BAR_SIDE + DESK + [PEN]

PARAMS = dict(seed=1)
FLOOR = "/turf/open/floor/plasteel"
ROOM_TABLE = {
    "kitchen": dict(area=KITCHEN, floor="/turf/open/floor/plasteel/cafeteria", name="Kitchen", label="KITCHEN"),
    "cold": dict(area=KITCHEN, floor="/turf/open/floor/plasteel/showroomfloor", name="Kitchen Cold Room",
                 label="COLD"),
    "hydro": dict(area=HYDRO, floor=FLOOR, name="Hydroponics", label="HYDRO"),
    "hydroback": dict(area=HYDRO, floor=FLOOR, name="Hydroponics Storage", label="BACK"),
}

KBLOCK = (147, 133, 154, 142)       # the kitchen and its cold room
HBLOCK = (156, 132, 163, 143)       # the garden and its back room


def authored(P):
    return {
        "K": Y((2, "cold"), (1.0, "kitchen")),
        "H": Y((3, "hydroback"), (1.0, "hydro")),
    }


def plans(P, fill=None):
    f = fill or authored(P)
    return [
        (KBLOCK, f["K"]),
        (HBLOCK, f["H"]),
        ((149, 143, 151, 143), "cold"),          # the cold room's row beside the kitchen chute
        ((155, 143, 155, 143), "hydroback"),     # in from the garden's chute
        ((162, 144, 163, 145), "hydroback"),     # the way up to the pen
    ]


def program(P):
    """Two blocks. The kitchen fronts the counter and the bar's doors; the cold room the kitchen chute; the garden
    its desk and glass doors; the back room the garden chute and the way up to the pen."""
    blocks = [
        solve.Block("K", KBLOCK, {"s": ("counter", 149, 152), "w": ("bar", 133, 136), "n": ("chute", 151, 152)}),
        solve.Block("H", HBLOCK, {"s": ("desk", 156, 162), "n": ("pen", 155, 163)}),
    ]
    W = solve.Want
    wants = [
        W("kitchen", 40, min=(5, 5), front=("counter", "bar")),
        W("cold", 14, min=(3, 2), front=("chute",), anchors=[(151, 142)]),
        W("hydro", 60, min=(6, 6), front=("desk",)),
        W("hydroback", 20, min=(8, 3), front=("pen",), anchors=[(156, 143), (163, 143)]),
    ]
    return blocks, wants


LINK_PAIRS = [("kitchen", "cold"), ("hydro", "hydroback")]


def seeded(seed, tries=8):
    last = None
    for t in range(tries):
        P = dict(PARAMS)
        blocks, wants = program(P)
        trees, rects, report = solve.solve(blocks, wants, LINK_PAIRS, seed="%s.%d" % (seed, t), ratio=(0.25, 4.0),
                                           fill=True, fixed={"kitchen": "K", "cold": "K",
                                                             "hydro": "H", "hydroback": "H"})
        if trees is None:
            break
        g = graph(fill=trees)
        geo = g.run()
        geo.notes[:0] = report + ["seed %s: try %d, %d problems" % (seed, t, len(geo.problems))]
        last = (g, geo)
        if not geo.problems:
            break
    return last


LINKS = [keep(p, "kitchen") for p in COUNTER + BAR_SIDE] + [
    keep((152, 143), "cold"), keep((154, 143), "hydroback"),
    keep(DESK[0], "hydro"), keep(DESK[1], "hydro"), keep(GARDEN_DOORS[0], "hydro"), keep(GARDEN_DOORS[1], "hydro"),
    keep(PEN, "hydroback"),
    door("kitchen", "cold", name="Kitchen Cold Room", kind="public", access="28"),
    door("kitchen", "hydro", type="windoor", name="Hydroponics Desk", access="35"),
    door("hydro", "hydroback", name="Hydroponics Storage", kind="public", glass=True, access="35"),
    glass("hydro", "hydroback"),
]


SEED = int(os.environ.get("MAPFORGE_SEED", "1"))
if SEED != 1:
    PARAMS["seed"] = SEED
    NAME += "_s%d" % SEED


def graph(fill=None, **over):
    P = dict(PARAMS)
    P.update(over)
    g = G.Graph(NAME, **P)
    g.add("outline", shell.outline, view="kind", base=BASE_MAP, bbox=BBOX, in_zone=in_zone,
          keep=GLASS + [(153, 143)], gates=GATES + GARDEN_DOORS)
    g.add("slice", shell.slice_rooms, view="rooms", plans=plans(P, fill), rooms=ROOM_TABLE)
    g.add("tidy", shell.tidy, view="rooms")
    g.add("openings", shell.openings, view="rooms", links=LINKS)
    g.add("fields", shell.fields, view="fields")
    g.add("furnish", furnish.furnish, view="items", assets=assets.ASSETS)
    return g


_graph, _geo = seeded(SEED) if SEED != 1 else (graph(), None)
_geo = _geo or _graph.run()
globals().update(emit.blueprint(_geo, NAME, extra=dict(STYLE="meta", DISPOSALS="route", DRESS_HALL_FRONT=True,
                                                       BASE=BASE_MAP)))


def main():
    g, geo = _graph, _geo
    out = os.path.join(ROOT, "data", "previews", "mapforge", "proc")
    paths = g.pictures(out, tile=20)
    G.sheet(paths, os.path.join(out, NAME + "_nodes.png"), cols=3)
    G.draw(geo, "items", os.path.join(out, NAME + "_furnish_big.png"), tile=30, title="furnish")
    for n in geo.notes:
        print(n)
    for p in geo.problems:
        print("PROBLEM", p)
    print("pictures:", os.path.relpath(os.path.join(out, NAME + "_nodes.png"), ROOT))


if __name__ == "__main__":
    main()
